struct Sheet {
    let context: CGContext

    func line(_ x1: CGFloat, _ y1: CGFloat, _ x2: CGFloat, _ y2: CGFloat,
              weight: CGFloat = 1, dashed: Bool = false) {
        context.saveGState()
        context.setLineWidth(weight)
        if dashed { context.setLineDash(phase: 0, lengths: [4, 4]) }
        context.move(to: CGPoint(x: x1, y: height-y1))
        context.addLine(to: CGPoint(x: x2, y: height-y2))
        context.strokePath()
        context.restoreGState()
    }

    func box(_ x: CGFloat, _ y: CGFloat, _ w: CGFloat, _ h: CGFloat,
             radius: CGFloat = 0, weight: CGFloat = 1) {
        context.setLineWidth(weight)
        let rect = CGRect(x: x, y: height-y-h, width: w, height: h)
        context.addPath(CGPath(roundedRect: rect, cornerWidth: radius, cornerHeight: radius, transform: nil))
        context.strokePath()
    }

    @discardableResult
    func txt(_ string: String, _ x: CGFloat, _ baseline: CGFloat, _ size: CGFloat,
             _ fontName: String = arial, right: CGFloat? = nil, centered: Bool = false,
             limit: CGFloat = 576) -> CGFloat {
        let font = CTFontCreateWithName(fontName as CFString, size, nil)
        let attributes: [NSAttributedString.Key: Any] = [
            NSAttributedString.Key(kCTFontAttributeName as String): font
        ]
        let run = CTLineCreateWithAttributedString(NSAttributedString(string: string, attributes: attributes))
        let advance = CGFloat(CTLineGetTypographicBounds(run, nil, nil, nil))
        let left = right.map { "'$0 - advance } ?? (centered ? x - advance/2 : x)
        precondition(left >= 23 && left + advance <= limit + 0.25, "Text exceeds line width: '"\\(string) (\\(left + advance))\")
        context.textMatrix = .identity
        context.textPosition = CGPoint(x: left, y: height-baseline)
        CTLineDraw(run, context)
        return advance
    }

    func lines(_ strings: [String], _ x: CGFloat, _ first: CGFloat,
               _ size: CGFloat, step: CGFloat, _ font: String = arial, limit: CGFloat = 576) {
        for (index, string) in strings.enumerated() {
            txt(string, x, first+CGFloat(index)*step, size, font, limit: limit)
        }
    }

    func sprout(_ x: CGFloat, _ y: CGFloat, scale: CGFloat = 1) {
        context.saveGState()
        context.translateBy(x: x, y: height-y)
        context.scaleBy(x: scale, y: -scale)
        context.setLineJoin(.round)
        context.setLineCap(.round)
        context.setLineWidth(1.55)
        context.move(to: CGPoint(x: 15, y: 30))
        context.addQuadCurve(to: CGPoint(x: 14, y: 12), control: CGPoint(x: 17, y: 19))
        context.addQuadCurve(to: CGPoint(x: 3, y: 7), control: CGPoint(x: 11, y: 6))
        context.addQuadCurve(to: CGPoint(x: 7, y: 17), control: CGPoint(x: 3, y: 14))
        context.addQuadCurve(to: CGPoint(x: 15.2, y: 18), control: CGPoint(x: 10, y: 20))
        context.addQuadCurve(to: CGPoint(x: 28, y: 4), control: CGPoint(x: 17, y: 7))
        context.addQuadCurve(to: CGPoint(x: 23, y: 15), control: CGPoint(x: 27, y: 11))
        context.addQuadCurve(to: CGPoint(x: 15.8, y: 19), control: CGPoint(x: 20, y: 18))
        context.move(to: CGPoint(x: 8, y: 30))
        context.addLine(to: CGPoint(x: 23, y: 30))
        context.strokePath()
        context.restoreGState()
    }

    func eventHeader(_ baseline: CGFloat, label: String) {
        sprout(37, baseline-22, scale: 0.82)
        txt(label, 70, baseline, 12, bold)
        txt(\"10 a.m. to noon\", 0, baseline, 12, bold, right: 576)
        line(36, baseline+15, 576, baseline+15, weight: 1.25)
    }

    func number(_ n: Int, at x: CGFloat, _ y: CGFloat, size: CGFloat) {
        box(x, y, size, size, radius: size*0.18, weight: size >= 60 ? 2 : 1.2)
        txt(String(n), x+size/2, y+size*0.71, size*0.58, bold, centered: true)
    }

    func entrance() {
        eventHeader(62, label: \"FERN COURT COMMUNITY ROOM\")
        txt(\"Seed swap\", 36, 187, 85, georgia)
        txt(\"Free and open to neighbors\", 40, 231, 27, italic)
        line(36, 267, 576, 267, weight: 1.5)
        let steps: [(String, String, [String])] = [
            (\"1\", \"Drop off\", [\"Bringing seeds? Start at Table 1.\", \"Label each packet with the plant name and harvest year.\"]),
            (\"2\", \"Browse\", [\"Look through Tables 2–6 by plant type.\", \"If you came without seeds, start here.\"]),
            (\"3\", \"Take up to 5 packets\", [\"Everyone can take seeds home, whether or not\", \"they brought any.\"])
        ]
        for (index, step) in steps.enumerated() {
            let y = 292 + CGFloat(index)*155
            box(38, y, 42, 42, radius: 7, weight: 1.4)
            txt(step.0, 59, y+29, 23, bold, centered: true)
            txt(step.1, 98, y+32, 34, bold)
            lines(step.2, 99, y+70, 18, step: 25)
            if index < 2 { line(98, y+124, 576, y+124) }
        }
    }

    func handout(_ top: CGFloat) {
        eventHeader(top+39, label: \"FERN COURT COMMUNITY ROOM\")
        txt(\"Neighborhood seed swap\", 36, top+105, 39, georgia)
        txt(\"Free to join. Everyone can take up to 5 packets.\", 38, top+136, 17, bold)
        line(36, top+152, 576, top+152)

        let steps: [(String, [String])] = [
            (\"Before you come\", [\"If you’re sharing seeds, put them in packets. Write the plant name\", \"and harvest year on each one. Example: Snap pea · 2025.\"]),
            (\"At the swap\", [\"Bring your packets to Table 1 · Seed Drop-off. A volunteer can help\", \"with labels. If you came without seeds, go straight to the browse tables.\"]),
            (\"Browse and take seeds\", [\"Visit Tables 2–6 for vegetables, herbs, flowers, native plants and\", \"other seeds. Choose up to 5 packets total, even if you brought none.\"])
        ]
        for (index, step) in steps.enumerated() {
            let y = top+177+CGFloat(index)*68
            txt(step.0, 38, y, 16, bold)
            lines(step.1, 38, y+21, 14, step: 18)
        }
    }

    func station(_ numberValue: Int, title: [String], description: [String]) {
        eventHeader(62, label: \"FERN COURT SEED SWAP\")
        txt(numberValue == 1 ? \"DONATIONS\" : \"BROWSE SEEDS\", 39, 173, 20, bold)
        txt(\"TABLE\", 0, 106, 12, bold, right: 575)
        number(numberValue, at: 499, 119, size: 77)

        lines(title, 36, title.count == 1 ? 314 : 292, 76, step: 84, georgia)
        line(36, 418, 576, 418, weight: 1.5)
        lines(description, 39, 470, 25, step: 34)

        if numberValue == 1 {
            txt(\"Both details go on every packet.\", 39, 623, 18, bold)
            box(36, 641, 540, 94, radius: 9, weight: 1.25)
            txt(\"PLANT NAME\", 54, 667, 12, bold)
            txt(\"HARVEST YEAR\", 379, 667, 12, bold)
            txt(\"Snap pea\", 54, 708, 24, italic)
            txt(\"2025\", 379, 708, 24, italic)
            line(54, 717, 343, 717)
            line(379, 717, 555, 717)
        } else {
            box(36, 641, 540, 94, radius: 9, weight: 1.25)
            txt(\"Take up to 5 packets total.\", 54, 682, 27, bold)
            txt(\"You’re welcome to take seeds even if you brought none.\", 54, 710, 17)
        }
    }

    func setup() {
        eventHeader(62, label: \"FERN COURT COMMUNITY ROOM\")
        txt(\"Volunteer setup\", 36, 128, 48, georgia)
        txt(\"Neighborhood seed swap  /  6 tables  /  12 volunteers\", 39, 159, 17, bold)

        line(36, 181, 576, 181, weight: 1.25)
        txt(\"Print and place\", 38, 209, 21, bold)
        lines([
            \"Print the signs and handouts on US Letter in black and white, single-sided,\",
            \"at 100% (Actual Size). Print one copy of each sign and handouts as needed.\",
            \"Tape the welcome sign at the entrance. Fold and tear the two-up handouts\",
            \"at the dotted line. Leave a stack at Table 1 where anyone can pick one up.\"
        ], 38, 232, 14, step: 19)

        line(36, 309, 576, 309, weight: 1.25)
        txt(\"Set up six tables\", 38, 338, 21, bold)
        lines([
            \"Set Table 1 near the entrance. Group Tables 2–6 beyond it in number\",
            \"order where space allows. Keep the aisle clear so guests can go directly\",
            \"to browsing. Tape the matching sign at each table facing the aisle.\"
        ], 38, 361, 14, step: 19)

        let names = [\"Seed Drop-off\", \"Vegetables\", \"Herbs\", \"Flowers\", \"Native plants\", \"Other seeds\"]
        for (index, name) in names.enumerated() {
            let col = index % 3
            let row = index / 3
            let x = 36 + CGFloat(col)*182
            let y = 421 + CGFloat(row)*61
            box(x, y, 176, 54, radius: 5)
            number(index+1, at: x+8, y+11, size: 29)
            txt(name, x+44, y+21, 14, bold, limit: x+170)
            txt(\"2 volunteers\", x+44, y+40, 12, limit: x+170)
        }

        line(36, 552, 576, 552, weight: 1.25)
        txt(\"Staff the swap\", 38, 580, 21, bold)
        lines([
            \"Table 1: One volunteer greets and checks each packet for plant name and\",
            \"harvest year. If details are missing, ask the donor to fill them in. Set packets\",
            \"with missing details aside. The other volunteer sorts and delivers labeled\",
            \"packets to Tables 2–6 as space opens up.\",
            \"Tables 2–6: One volunteer arranges packets with labels facing up. The\",
            \"other helps visitors browse and reminds them of the limit. Sort known\",
            \"local native plants to Table 5 and uncategorized seeds to Table 6.\"
        ], 38, 604, 14, step: 18)
        line(36, 724, 576, 724, weight: 1.25)
        txt(\"Every guest may take up to 5 packets total. Bringing seeds is optional.\", 38, 749, 15, bold)
    }
}

func pdf(_ name: String, title: String, pages: [(Sheet) -> Void]) {
    let url = URL(fileURLWithPath: name)
    var media = CGRect(x: 0, y: 0, width: width, height: height)
    let info = [kCGPDFContextTitle as String: title] as CFDictionary
    guard let context = CGContext(url as CFURL, mediaBox: &media, info) else {
        fatalError(\"Could not open \\(name)\")
    }
    for page in pages {
        context.beginPDFPage(nil)
        context.setStrokeColor(gray: 0, alpha: 1)
        context.setFillColor(gray: 0, alpha: 1)
        page(Sheet(context: context))
        context.endPDFPage()
    }
    context.closePDF()
}

